CREATE TABLE IF NOT EXISTS learning_resources(id text PRIMARY KEY, institution_id text NOT NULL REFERENCES institutions(id), title text NOT NULL, body text NOT NULL, cohort text NOT NULL, department text NOT NULL, faculty_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('Resource','Assignment')), due_date date, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(institution_id,faculty_id) REFERENCES users(institution_id,id), UNIQUE(institution_id,id), CHECK(kind<>'Assignment' OR due_date IS NOT NULL));
CREATE TABLE IF NOT EXISTS learning_submissions(id text PRIMARY KEY, institution_id text NOT NULL, resource_id text NOT NULL, student_id text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'Submitted', feedback text, version integer NOT NULL DEFAULT 1, submitted_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(institution_id,resource_id) REFERENCES learning_resources(institution_id,id), FOREIGN KEY(institution_id,student_id) REFERENCES students(institution_id,id), UNIQUE(resource_id,student_id));
CREATE TABLE IF NOT EXISTS service_requests(id text PRIMARY KEY, institution_id text NOT NULL, student_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('Certificate','Leave','Appeal')), title text NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'Submitted', reviewer_id text REFERENCES users(id), decision_reason text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(institution_id,student_id) REFERENCES students(institution_id,id));
